from debug import *

def func_val_to_hex_can(c):
    printf(c)
    c = int(c)
    printf(c)
    c = hex(c)[2:].upper()
    printf(c)
    if len(c) == 1:
        printf(type(c),c)
        c = '0' + c + "000000"
        printf(c)
    elif len(c) == 2:
        c = c + "000000"
    elif len(c) == 3:
        c = c + "00000"
    elif len(c) == 4:
        c = c[len(c) - 2:] + "  " + \
            c[len(c) - 4:len(c) - 2] + "0000"
    elif len(c) == 6:
        c = c[len(c) - 2:] + "  " + \
            c[len(c) - 4:len(c) - 2] + "  " + c[len(c) - 6:len(c) - 4] + "00"
    elif len(c) == 8:
        c = c[len(c) - 2:] + "  " + \
            c[len(c) - 4:len(c) - 2] + "  " + c[len(c) - 6:len(c) - 4] + "  " + c[len(c) - 8:len(c) - 6]
    return c

