def trans_neg_hex_to_dec(arg):
    arg = '0x' + arg
    arg = int(arg, 16)
    t = bin(arg)
    s = str.maketrans('01', '10')
    s1 = t[2:].translate(s)
    s2 = (int(s1, 2) + 1) * -1
    # printf(s2+1)
    return s2
