    if metric >269:
        text = list(text)
        for i in range(0,len(text)):
            printf(i)
            if i*7>269:
                if text[i] != ' ':
                    if flag==0:
                        j = i
                        flag=1
                    if flag==1:
                        while(True):
                            j-=1
                            if text[j]==' ':
                                text[j] = '\n'
                                break
                        break
                elif text[i] == ' ':
                    text[i] = '\n'
                    break
        text = ''.join(text)
        printf(text)
        return [text]
    else: return [text]

